<script setup lang="ts">
import { Delete, Edit, Plus, Refresh } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { onMounted, reactive, ref } from 'vue'

import { api } from '../api/client'
import PageHeader from '../components/PageHeader.vue'
import StatusTag from '../components/StatusTag.vue'
import { useSessionStore } from '../stores/session'

const session=useSessionStore();const loading=ref(false);const items=ref<any[]>([]);const status=ref('');const dialog=ref(false);const editing=ref<any>(null);const form=reactive({scope:'project',kind:'project_context',content:''})
async function load(){loading.value=true;try{items.value=(await api.get('/api/v1/memories',{params:{project_id:session.currentProjectId,status:status.value||undefined}})).data}catch(e){ElMessage.error(e instanceof Error?e.message:'记忆加载失败')}finally{loading.value=false}}
function open(item?:any){editing.value=item||null;form.scope=item?.scope||'project';form.kind=item?.kind||'project_context';form.content=item?.content||'';dialog.value=true}
async function save(){try{if(editing.value)await api.patch(`/api/v1/memories/${editing.value.memory_id}`,{content:form.content});else await api.post('/api/v1/memories/candidates',{project_id:form.scope==='project'?session.currentProjectId:null,...form});ElMessage.success('记忆候选已保存，需确认后生效');dialog.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'保存失败')}}
async function action(id:string,kind:'confirm'|'reject'){try{await api.post(`/api/v1/memories/${id}/${kind}`);ElMessage.success(kind==='confirm'?'记忆已确认':'记忆已拒绝');await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'操作失败')}}
async function remove(id:string){await ElMessageBox.confirm('确认删除这条长期记忆？','删除记忆',{type:'warning'});try{await api.delete(`/api/v1/memories/${id}`);ElMessage.success('记忆已删除');await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'删除失败')}}
onMounted(load)
</script>
<template><PageHeader title="长期记忆" description="用户确认后才进入向量索引；记忆用于理解上下文，不作为审查证据"><el-button type="primary" :icon="Plus" @click="open()">新建候选</el-button></PageHeader><div class="risk-strip">长期记忆不能作为 Evidence，也不会直接影响工程审查结论。</div><section class="section"><div class="section__body"><div class="toolbar"><el-select v-model="status" clearable placeholder="全部状态" style="width:130px" @change="load"><el-option label="待确认" value="pending"/><el-option label="已确认" value="confirmed"/><el-option label="已拒绝" value="rejected"/></el-select><span class="spacer"/><el-button :icon="Refresh" @click="load">刷新</el-button></div><el-table v-loading="loading" :data="items"><el-table-column prop="scope" label="范围" width="90"><template #default="s">{{s.row.scope==='project'?'项目':'用户'}}</template></el-table-column><el-table-column prop="kind" label="类型" width="140"/><el-table-column prop="content" label="内容" min-width="340"/><el-table-column prop="status" label="状态" width="100"><template #default="s"><StatusTag :status="s.row.status"/></template></el-table-column><el-table-column prop="created_at" label="创建时间" width="170"><template #default="s">{{new Date(s.row.created_at).toLocaleString()}}</template></el-table-column><el-table-column label="操作" width="220"><template #default="s"><el-button v-if="s.row.status==='pending'" link type="primary" @click="action(s.row.memory_id,'confirm')">确认</el-button><el-button v-if="s.row.status==='pending'" link @click="action(s.row.memory_id,'reject')">拒绝</el-button><el-button link :icon="Edit" @click="open(s.row)">编辑</el-button><el-button link type="danger" :icon="Delete" @click="remove(s.row.memory_id)">删除</el-button></template></el-table-column></el-table></div></section><el-dialog v-model="dialog" :title="editing?'编辑记忆':'新建记忆候选'" width="560px"><el-form label-position="top"><el-form-item label="范围"><el-radio-group v-model="form.scope"><el-radio-button value="project">当前项目</el-radio-button><el-radio-button value="user">当前用户</el-radio-button></el-radio-group></el-form-item><el-form-item label="类型"><el-input v-model="form.kind"/></el-form-item><el-form-item label="内容"><el-input v-model="form.content" type="textarea" :rows="5" maxlength="4000" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :disabled="!form.content.trim()" @click="save">保存候选</el-button></template></el-dialog></template>
